import java.util.Scanner;

public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    final int TAKAHASHI_INNINGS = 9;
    final int AOKI_INNINGS = 8;
    int[] A = new int[TAKAHASHI_INNINGS];
    int[] B = new int[AOKI_INNINGS];
    int sumTakahashi = 0;
    int sumAoki = 0;

    for (int i = 0; i < TAKAHASHI_INNINGS; i++) {
        A[i] = sc.nextInt();
        sumTakahashi += A[i];
    }

    for (int i = 0; i < AOKI_INNINGS; i++) {
        B[i] = sc.nextInt();
        sumAoki += B[i];
    }

    int diff = sumTakahashi - sumAoki;

    if (diff > 0) {
        System.out.println(diff + 1);
    } else {
        System.out.println(0);
    }
}
